import { useState, useEffect } from 'react';
import Post from '../post/Post';
import './photos.scss';

const Photos = () => {
  const [photos, setPhotos] = useState([]);
  const [error, setError] = useState(null);

  const getMediaType = (mediaUrl) => {
    if (!mediaUrl) return null;
    const ext = mediaUrl.split('.').pop().toLowerCase();
    if (['jpg', 'jpeg', 'png', 'gif'].includes(ext)) return 'image';
    return null;
  };

  const fetchPhotos = async () => {
    try {
      console.log('Photos: Fetching posts');
      const token = sessionStorage.getItem('token');
      if (!token) {
        throw new Error('No authentication token found');
      }

      const response = await fetch('http://localhost:5000/api/posts', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch posts');
      }

      const data = await response.json();
      const imagePosts = data.filter((post) => getMediaType(post.media) === 'image');
      console.log('Photos: Filtered image posts=', JSON.stringify(imagePosts, null, 2));
      setPhotos(imagePosts);
      setError(null);
    } catch (err) {
      console.error('Photos: Error fetching posts:', err.message);
      setError(err.message || 'Failed to load photos');
    }
  };

  useEffect(() => {
    fetchPhotos();

    const handleNewPost = () => {
      console.log('Photos: New post event received');
      fetchPhotos();
    };

    window.addEventListener('newPost', handleNewPost);

    return () => {
      window.removeEventListener('newPost', handleNewPost);
    };
  }, []);

  return (
    <div className="photos">
      {error && <p className="error">{error}</p>}
      {photos.length === 0 && !error ? (
        <p>No photos available</p>
      ) : (
        photos.map((post) => <Post key={post._id} post={post} />)
      )}
    </div>
  );
};

export default Photos;
